static const char *const kCegisFrameworkVersion =
    "v16-cff-cee-native-library";

enum CandidatePlannerKind {
    CANDIDATE_PLANNER_T1 = 0,
    CANDIDATE_PLANNER_CNF = 1,
    CANDIDATE_PLANNER_DNF = 2,
    CANDIDATE_PLANNER_PIP = 3,
    CANDIDATE_PLANNER_CPAH = 4,
    CANDIDATE_PLANNER_IGC_ORIGIN = 5,
    CANDIDATE_PLANNER_GC_LAMA = 6,
    CANDIDATE_PLANNER_GCPCES = 7,
    CANDIDATE_PLANNER_ICPCES = 8,
    CANDIDATE_PLANNER_CFF = 9,
    CANDIDATE_PLANNER_POND = 10,
    CANDIDATE_PLANNER_T0 = 11
};

enum CandidateRuntimeMode {
    CANDIDATE_RUNTIME_NATIVE = 0,
    CANDIDATE_RUNTIME_ISOLATED = 1
};

static bool is_gc_family_candidate(CandidatePlannerKind kind) {
    return kind == CANDIDATE_PLANNER_IGC_ORIGIN ||
           kind == CANDIDATE_PLANNER_GC_LAMA;
}

static bool is_remaining_cpces_gc_line(CandidatePlannerKind kind) {
    return kind == CANDIDATE_PLANNER_IGC_ORIGIN ||
           kind == CANDIDATE_PLANNER_GC_LAMA ||
           kind == CANDIDATE_PLANNER_GCPCES ||
           kind == CANDIDATE_PLANNER_ICPCES;
}

static bool uses_dnf_native_sample_completion(CandidatePlannerKind kind) {
    // DNF-native component sample completion is a DNF/CNF/PIP/T0-family
    // acceleration.  Do not apply it to gCPCES/iCPCES/GC/iGC: those planners
    // are sensitive to native sample/world structure and should receive their
    // own renderer-specific surface adaptation instead of extra DNF-style
    // completion samples.
    return kind == CANDIDATE_PLANNER_DNF;
}

static std::vector<std::string> pddl_form_arguments(
        const std::string &form);

static const char *candidate_runtime_mode_name(
        CandidateRuntimeMode mode) {
    return mode == CANDIDATE_RUNTIME_NATIVE
        ? "NATIVE" : "ISOLATED";
}

enum RefinedPddlProfile {
    REFINED_PDDL_T1 = 0,
    REFINED_PDDL_CPA_FAMILY = 1,
    REFINED_PDDL_CPAH = 2,
    REFINED_PDDL_GC_LAMA = 3,
    REFINED_PDDL_IGC = 4,
    REFINED_PDDL_GCPCES = 5,
    REFINED_PDDL_ICPCES = 6,
    REFINED_PDDL_DNF_STRUCT = 7,
    REFINED_PDDL_DNF_NATIVE = 11,
    REFINED_PDDL_PIP_LARGE_ONEOF_OR = 12,
    REFINED_PDDL_CFF_NATIVE = 13,
    REFINED_PDDL_CFF_EXACT = 14,
    REFINED_PDDL_CFF_STRUCT = 8,
    REFINED_PDDL_T0_STRUCT = 9,
    REFINED_PDDL_POND_STRUCT = 10,
    REFINED_PDDL_T1_CGCFF_STRUCT = 15,
    REFINED_PDDL_GCPCES_STRUCT = 16,
    REFINED_PDDL_ICPCES_STRUCT = 17,
    REFINED_PDDL_GC_IGC_STRUCT = 18
};

static bool is_gc_native_profile(RefinedPddlProfile profile) {
    return profile == REFINED_PDDL_GC_LAMA ||
           profile == REFINED_PDDL_IGC;
}

static bool is_gc_igc_structured_profile(RefinedPddlProfile profile) {
    return profile == REFINED_PDDL_GC_IGC_STRUCT;
}

static bool is_gcpces_icpces_structured_profile(RefinedPddlProfile profile) {
    return profile == REFINED_PDDL_GCPCES_STRUCT ||
           profile == REFINED_PDDL_ICPCES_STRUCT;
}

static bool is_remaining_native_structured_profile(RefinedPddlProfile profile) {
    return is_gcpces_icpces_structured_profile(profile) ||
           is_gc_igc_structured_profile(profile);
}

static bool is_cpa_family_planner(CandidatePlannerKind kind) {
    return kind == CANDIDATE_PLANNER_CNF ||
           kind == CANDIDATE_PLANNER_DNF ||
           kind == CANDIDATE_PLANNER_PIP;
}

static bool is_cpa_t0_family_renderer_planner(CandidatePlannerKind kind) {
    return is_cpa_family_planner(kind) ||
           kind == CANDIDATE_PLANNER_T0;
}

static bool is_t1_cff_family_renderer_planner(CandidatePlannerKind kind) {
    return kind == CANDIDATE_PLANNER_T1 ||
           kind == CANDIDATE_PLANNER_CFF;
}

static std::string trim(const std::string &s);
static std::string lower_ascii(const std::string &s);
static std::string getenv_string(const char *name, const std::string &fallback);

static bool is_cpah_adaptive_renderer_planner(CandidatePlannerKind kind) {
    return kind == CANDIDATE_PLANNER_CPAH;
}

static bool is_pond_adaptive_renderer_planner(CandidatePlannerKind kind) {
    return kind == CANDIDATE_PLANNER_POND;
}

static bool is_adaptive_generalized_renderer_planner(CandidatePlannerKind kind) {
    return is_cpa_t0_family_renderer_planner(kind) ||
           is_t1_cff_family_renderer_planner(kind) ||
           is_cpah_adaptive_renderer_planner(kind) ||
           is_pond_adaptive_renderer_planner(kind) ||
           is_remaining_cpces_gc_line(kind);
}

static std::string adaptive_generalized_profile_setting(CandidatePlannerKind kind) {
    if (kind == CANDIDATE_PLANNER_IGC_ORIGIN ||
        kind == CANDIDATE_PLANNER_GC_LAMA) {
        return lower_ascii(trim(getenv_string(
            kind == CANDIDATE_PLANNER_IGC_ORIGIN ?
                "IGC_IGC_RENDER_PROFILE" : "IGC_GC_LAMA_RENDER_PROFILE",
            getenv_string("IGC_GC_IGC_RENDER_PROFILE",
                getenv_string("IGC_GC_FAMILY_RENDER_PROFILE",
                    getenv_string("IGC_ADAPTIVE_RENDER_PROFILE", "adaptive"))))));
    }
    if (kind == CANDIDATE_PLANNER_GCPCES ||
        kind == CANDIDATE_PLANNER_ICPCES) {
        return lower_ascii(trim(getenv_string(
            kind == CANDIDATE_PLANNER_GCPCES ?
                "IGC_GCPCES_RENDER_PROFILE" : "IGC_ICPCES_RENDER_PROFILE",
            getenv_string("IGC_CPCES_RENDER_PROFILE",
                getenv_string("IGC_ADAPTIVE_RENDER_PROFILE", "adaptive")))));
    }
    if (kind == CANDIDATE_PLANNER_POND) {
        return lower_ascii(trim(getenv_string(
            "IGC_POND_RENDER_PROFILE",
            getenv_string("IGC_ADAPTIVE_RENDER_PROFILE", "adaptive"))));
    }
    if (kind == CANDIDATE_PLANNER_CPAH) {
        return lower_ascii(trim(getenv_string(
            "IGC_CPAH_RENDER_PROFILE",
            getenv_string("IGC_ADAPTIVE_RENDER_PROFILE", "adaptive"))));
    }
    if (is_t1_cff_family_renderer_planner(kind)) {
        return lower_ascii(trim(getenv_string(
            kind == CANDIDATE_PLANNER_T1 ?
                "IGC_T1_RENDER_PROFILE" : "IGC_CFF_RENDER_PROFILE",
            getenv_string("IGC_T1_CFF_RENDER_PROFILE",
                getenv_string("IGC_ADAPTIVE_RENDER_PROFILE", "adaptive")))));
    }
    return lower_ascii(trim(getenv_string(
        "IGC_CPA_FAMILY_RENDER_PROFILE",
        getenv_string("IGC_DNF_RENDER_PROFILE",
            getenv_string("IGC_ADAPTIVE_RENDER_PROFILE", "adaptive")))));
}

static RefinedPddlProfile refined_pddl_profile(CandidatePlannerKind kind) {
    // Unified literature reconstruction path.
    //
    // CFF is the mature reference line in this repository: it constructs the
    // candidate subproblem from the accumulated counterexample set B through
    // the CGCFF/JNU reconstruct-problem method (Y extraction,
    // separate-literals(I,Y), known-literal promotion, residual ONF/DNF
    // emission) without selector predicates, size thresholds, domain-name
    // fallbacks, or original-problem passthrough.
    //
    // DNF/CNF/PIP/T0 share the DNF-structured renderer, which preserves the
    // same reconstruction semantics but emits the PDDL dialect accepted by the
    // CPA-family front-ends.  T1 is deliberately routed to the CFF-structured
    // renderer rather than to its older sample-summary renderer: the generated
    // syntax is the common safe subset accepted by T1 and CFF ((unknown ...),
    // positive atomic ONEOF, and OR clauses over literals) while preserving
    // term-level correlations by compiling unsupported compound ONF/DNF
    // residuals into supported OR clauses.  The final iGC verifier remains the
    // only authority for accepting a plan on the original problem.
    // DNF/CNF/PIP accept the same CPA-family PDDL subset in the inspected
    // benchmarks.  The remaining gCPCES/iCPCES/GC/iGC lines share the same
    // adaptive CGCFF reconstruction policy, but they must not share the DNF
    // surface renderer.  gCPCES/iCPCES use an outer AND under :init like their
    // native benchmarks, while GC-LAMA/iGC intentionally share a direct-init
    // surface with no top-level AND and no UNKNOWN forms.  Only the external
    // runtime invocation differs for GC-LAMA vs iGC.
    // T0 is close enough at the reconstructed-problem level to
    // share the same adaptive generalized CGCFF renderer, but it still passes
    // through the T0-Compatible Intermediate PDDL (TCIP) surface-normalisation
    // layer immediately before translator-t0 is invoked.  Thus T0 now gets the
    // same progressive -> semantic-closure -> late component-preserve semantic
    // policy as DNF, while retaining T0-specific parser repairs for old
    // translator limitations.  POND is also routed through the adaptive
    // generalized reconstruction policy, but its surface renderer stays
    // POND-specific: UNKNOWN is never emitted directly and is converted to
    // Boolean ONEOF p/(not p), while late fallback preserves only
    // POND-compatible ONEOF/OR structure.
    if (kind == CANDIDATE_PLANNER_DNF ||
        kind == CANDIDATE_PLANNER_CNF ||
        kind == CANDIDATE_PLANNER_PIP ||
        kind == CANDIDATE_PLANNER_T0)
        return REFINED_PDDL_DNF_NATIVE;

    if (kind == CANDIDATE_PLANNER_GCPCES)
        return REFINED_PDDL_GCPCES_STRUCT;
    if (kind == CANDIDATE_PLANNER_ICPCES)
        return REFINED_PDDL_ICPCES_STRUCT;
    if (kind == CANDIDATE_PLANNER_IGC_ORIGIN ||
        kind == CANDIDATE_PLANNER_GC_LAMA)
        return REFINED_PDDL_GC_IGC_STRUCT;

    if (kind == CANDIDATE_PLANNER_T1)
        return REFINED_PDDL_T1_CGCFF_STRUCT;
    if (kind == CANDIDATE_PLANNER_CFF)
        return REFINED_PDDL_CFF_STRUCT;
    if (kind == CANDIDATE_PLANNER_POND)
        return REFINED_PDDL_POND_STRUCT;
    // CNF/DNF/PIP are covered together with T0 above.
    if (kind == CANDIDATE_PLANNER_CPAH) return REFINED_PDDL_CPAH;
    if (kind == CANDIDATE_PLANNER_IGC_ORIGIN)
        return REFINED_PDDL_IGC;
    if (kind == CANDIDATE_PLANNER_GC_LAMA)
        return REFINED_PDDL_GC_LAMA;
    if (kind == CANDIDATE_PLANNER_GCPCES) return REFINED_PDDL_GCPCES;
    if (kind == CANDIDATE_PLANNER_ICPCES) return REFINED_PDDL_ICPCES;
    return REFINED_PDDL_CPA_FAMILY;
}

