        return "cnf_pip_t0_cgcff_reconstruct_problem_oneof_or";
    case REFINED_PDDL_DNF_NATIVE:
        return "dnf_aligned_adaptive_generalized_cgcff_oneof_or";
    case REFINED_PDDL_PIP_LARGE_ONEOF_OR:
        return "pip_native_preserve_oneof_except_multi_large_position_oneof_as_or";
    case REFINED_PDDL_CFF_NATIVE:
        return "deprecated_cff_native_disabled_for_pure_cgcff";
    case REFINED_PDDL_CFF_EXACT:
        return "deprecated_cff_exact_selector_disabled_for_pure_cgcff";
    case REFINED_PDDL_CFF_STRUCT:
        return "cff_adaptive_generalized_cgcff_onf_dnf";
    case REFINED_PDDL_T0_STRUCT:
        return "deprecated_t0_old_t1_cff_profile_do_not_use";
    case REFINED_PDDL_POND_STRUCT:
        return "pond_adaptive_generalized_cgcff_oneof_or_no_unknown";
